from functools import cache


@cache
def all_possible_fbt(n):
    if n % 2 == 0:
        return []
    if n == 1:
        return [TreeNode(0)]
    out = []
    for left in range(1, n, 2):
        for l in all_possible_fbt(left):
            for r in all_possible_fbt(n - 1 - left):
                out.append(TreeNode(0, l, r))
    return out
